typedef struct blur_window {
    uint32_t alpha;
    uint32_t red;
    uint32_t green;
    uint32_t blue;
    int size;
} blur_window;

static inline void blur_window_reset(blur_window *w) {
    w->alpha = 0;
    w->red   = 0;
    w->green = 0;
    w->blue  = 0;
    w->size  = 0;
}

static inline void blur_window_add(blur_window *w, uint32_t *pixel, float weight) {
    w->alpha += color_a(*pixel) * weight;
    w->red   += color_r(*pixel) * weight;
    w->green += color_g(*pixel) * weight;
    w->blue  += color_b(*pixel) * weight;
    w->size  += 1;
}

static inline void blur_window_remove(blur_window *w, uint32_t *pixel, float weight) {
    w->alpha -= color_a(*pixel) * weight;
    w->red   -= color_r(*pixel) * weight;
    w->green -= color_g(*pixel) * weight;
    w->blue  -= color_b(*pixel) * weight;
    w->size  -= 1;
}

static inline void blur_window_collect_horizontally(blur_window *w, int curr_x, int y, int radius, gbuffer *gb) {
    float *gaussian_kernels = get_gaussian_kernel(radius);

    for (int offset = -radius; offset <= +radius; offset++) {
        if (curr_x + offset < 0) continue;
        if (curr_x + offset >= gb->area.size.width) continue;

        uint32_t *pixel = _pixel_ptr(gb, curr_x + offset, y);
        float weight = gaussian_kernels[offset + radius];
        blur_window_add(w, pixel, weight);
    }
}

static inline void blur_window_collect_vertically(blur_window *w, int x, int curr_y, int radius, gbuffer *gb) {
    float *gaussian_kernels = get_gaussian_kernel(radius);

    for (int offset = -radius; offset <= +radius; offset++) {
        if (curr_y + offset < 0) continue;
        if (curr_y + offset >= gb->area.size.height) continue;

        uint32_t *pixel = _pixel_ptr(gb, x, curr_y + offset);
        float weight = gaussian_kernels[offset + radius];
        blur_window_add(w, pixel, weight);
    }
}

static inline color blur_window_apply_color(blur_window *w, color clr) {
    if (w->size == 0) return clr;
    return color_argb(color_a(clr), w->red, w->green, w->blue);
}

static inline color blur_window_apply_alpha(blur_window *w, color clr) {
    if (w->size == 0) return clr;
    return color_with_alpha(w->alpha, clr);
}



